package br.com.admeclesial.application.financeiro; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.FornecedorRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class FornecedorApplicationService { final FornecedorRepository r; public FornecedorApplicationService(FornecedorRepository r){this.r=r;} @Transactional public Fornecedor criar(FornecedorRequest x){var e=new Fornecedor();e.setTipoPessoa(x.tipoPessoa());e.setNome(x.nome().trim());e.setCpfCnpj(x.cpfCnpj());e.setEmail(x.email());e.setTelefone(x.telefone());e.setAtivo(x.ativo()==null||x.ativo());return r.save(e);} @Transactional(readOnly=true) public List<Fornecedor> listar(){return r.findAll();}}